const items = $input.all();
const item = items[0];
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);

if (binaryKeys.length === 0) {
  throw new Error('Aucune piece jointe trouvee');
}

const validExtensions = ['pdf', 'doc', 'docx', 'png', 'jpg', 'jpeg', 'tiff'];
let cvKey = null;

for (const key of binaryKeys) {
  const filename = (binary[key].fileName || '').toLowerCase();
  const isValid = validExtensions.some(ext => filename.endsWith('.' + ext));
  if (isValid) {
    cvKey = key;
    break;
  }
}

if (!cvKey) {
  throw new Error('Aucun fichier CV valide parmi: ' + binaryKeys.map(k => binary[k].fileName).join(', '));
}

return [{
  json: {
    cv_filename: binary[cvKey].fileName,
    cv_mimetype: binary[cvKey].mimeType
  },
  binary: {
    data: binary[cvKey]
  }
}];

